var zhangXuefengResearchEntries = []KnowledgeEntry{
	{Title: "2026本科专业目录怎么使用", Category: "专业选择", Tags: []string{"本科专业目录", "专业代码", "官方资料"}, Content: "教育部《普通高等学校本科专业目录（2026年）》是核对专业名称、代码、所属门类和学位类型的基准。目录存在基本专业、特设专业和国家控制布点专业等差异，但进入目录不等于某校一定招生，也不等于就业有保证；还要核对目标学校当年招生章程与培养方案。来源：https://www.moe.gov.cn/srcsite/A08/moe_1034/s3882/202604/W020260427440749576927.pdf；核验：2026-06-28。"},
	{Title: "专业会随产业需求动态调整", Category: "专业选择", Tags: []string{"专业调整", "产业需求", "教育部"}, Content: "教育部等五部门的学科专业调整方案强调面向科技前沿、经济主战场、国家重大需求和人民生命健康优化专业供给。因此，不能把今天的热门专业视为永久热门。判断时应同时看专业设置变化、学校培养能力、区域产业和岗位需求。来源：https://www.moe.gov.cn/srcsite/A08/s7056/202304/t20230404_1054230.html；核验：2026-06-28。"},
	{Title: "位次比分数更适合跨年比较", Category: "高考志愿", Tags: []string{"位次", "分数", "志愿填报"}, Content: "跨年度比较院校与专业录取难度时，优先使用本省同科类或同选科组合的位次，而不是直接比较裸分。仍需考虑招生计划、批次合并、选科要求和大小年波动，至少准备冲、稳、保三层并服从本省正式志愿规则。"},
	{Title: "阳光志愿只能辅助不能代填", Category: "高考志愿", Tags: []string{"阳光高考", "模拟筛选", "官方系统"}, Content: "阳光高考的阳光志愿可基于往年录取情况、位次与偏好做模拟筛选，并展示专业满意度和毕业去向等参考数据；正式填报仍必须进入考生所在省份志愿系统。提前批、艺术、体育等特殊类型还应以省级考试机构和高校说明为准。来源：https://gaokao.chsi.com.cn/zyck/zy/；核验：2026-06-28。"},
	{Title: "招生章程核验清单", Category: "高考志愿", Tags: []string{"招生章程", "录取规则", "核验"}, Content: "报考前逐校核对当年招生章程：选科或科目要求、体检与单科限制、外语语种、专业级差或分配规则、转专业规则、校区、学费、住宿、培养模式和退档条件。第三方页面只用于发现线索，最终以省级考试机构和学校招生网为准。"},
	{Title: "平行志愿的风险控制", Category: "高考志愿", Tags: []string{"平行志愿", "冲稳保", "退档"}, Content: "平行志愿降低了院校选择风险，但没有消除专业调剂、身体限制、单科要求和退档风险。方案应按本省规则排列梯度，检查每个志愿最不愿接受的专业与校区，并明确是否接受调剂。不能只看最低投档线。"},
	{Title: "院校层次不能替代专业培养质量", Category: "院校选择", Tags: []string{"院校选择", "培养质量", "学科资源"}, Content: "院校标签只能说明部分筛选信号，不能替代具体专业判断。核对课程设置、师资方向、实验与实习条件、保研或升学出口、校招企业、毕业去向和校区资源。对目标岗位而言，学校、专业、城市的权重应由招聘门槛和培养资源决定。"},
	{Title: "城市选择看产业密度与生活成本", Category: "城市选择", Tags: []string{"城市", "产业", "生活成本"}, Content: "城市价值不只是一线或新一线标签。应比较目标行业企业密度、实习和校招机会、公共部门岗位、房租与通勤、落户政策、家庭支持距离和毕业后迁移难度。读书城市不必等于长期定居城市，但实习密集行业会明显受地域影响。"},
	{Title: "职业分类用于扩展岗位视野", Category: "职业规划", Tags: []string{"职业分类", "岗位地图", "人社部"}, Content: "《中华人民共和国职业分类大典（2022年版）》提供规范职业名称和主要工作任务，可用来把宽泛的专业兴趣展开为具体岗位，再去招聘平台验证要求。职业目录描述职业，不代表岗位数量、薪资或增长保证。来源：https://www.sz.gov.cn/attachment/1/1509/1509585/11457697.pdf；核验：2026-06-28。"},
	{Title: "数字职业不等于计算机专业专属", Category: "职业规划", Tags: []string{"数字职业", "复合能力", "AI"}, Content: "2022版职业分类大典首次标识97个数字职业，分布在多个行业。数字化机会不仅属于计算机专业，也需要行业知识、数据能力和工具使用的组合。选择专业时应判断自己能形成的复合能力，而不是只追逐带有智能、数字名称的新专业。来源：https://chinajob.mohrss.gov.cn/c/2022-10-28/363398.shtml；核验：2026-06-28。"},
	{Title: "招聘样本的正确采集方法", Category: "职业规划", Tags: []string{"招聘分析", "岗位样本", "就业倒推"}, Content: "为目标岗位至少采集不同城市、不同规模单位和不同招聘季的样本，记录学历、专业、技能、证书、经验和地点要求。区分校招与社招，避免用一个头部企业岗位代表整个行业。国家大学生就业服务平台可作为校招与实习入口之一。来源：https://www.ncss.cn/；核验：2026-06-28。"},
	{Title: "毕业去向数据的口径陷阱", Category: "职业规划", Tags: []string{"就业数据", "统计口径", "毕业去向"}, Content: "阅读就业质量报告时要确认年份、学院或专业样本量、升学是否计入去向落实、灵活就业口径、薪酬统计方式和未回应比例。学校整体数据不能直接代表某个专业，平均数也不能代表普通学生。优先看分专业分层数据和连续多年趋势。"},
	{Title: "实习是低成本职业实验", Category: "职业规划", Tags: []string{"实习", "职业验证", "实践"}, Content: "实习、项目、职业访谈和短期课程可在做出高成本选择前验证工作内容、环境和能力匹配。教育部就业行动也强调组织毕业生进入企事业单位、科技园区、实习基地和基层一线参加实践。来源：https://www.moe.gov.cn/jyb_xwfb/gzdt_gzdt/s5987/202501/t20250115_1175704.html；核验：2026-06-28。"},
	{Title: "学历门槛与能力门槛分开看", Category: "职业规划", Tags: []string{"学历", "能力", "筛选门槛"}, Content: "先判断岗位是否存在硬性学历、院校、资格或专业门槛，再判断通过筛选后靠什么能力竞争。考研可能改善入场资格，却不会自动补齐项目、实习、沟通和专业能力；同样，能力强也未必能绕过所有硬门槛。"},
	{Title: "2026考研信息以研招网和招生单位为准", Category: "考研择校", Tags: []string{"2026考研", "研招网", "招生规定"}, Content: "2026年硕士招生仍包括初试与复试，招生单位依据计划、需求和办学条件确定专业招生人数；全日制与非全日制执行统一考试招生政策和标准，但学习与就业方式不同。具体专业目录、科目、推免和复试规则必须查当年研招网及招生单位公告。来源：https://yz.chsi.com.cn/kyzx/jybzc/202509/20250924/2293432108-4.html；核验：2026-06-28。"},
	{Title: "学硕专硕按培养目标选择", Category: "考研择校", Tags: []string{"学术学位", "专业学位", "培养目标"}, Content: "学术学位更侧重学术创新与研究训练，专业学位更侧重解决实际问题和职业实践，但具体培养质量取决于学校、导师、课程和项目。不要仅凭名称判断难度或就业，应核对培养方案、实习要求、导师方向和毕业去向。"},
	{Title: "全日制与非全日制核验清单", Category: "考研择校", Tags: []string{"全日制", "非全日制", "定向就业"}, Content: "比较全日制与非全日制时，核对学习方式、学制、学费、住宿、奖助、档案、定向就业要求、授课时间、培养资源和目标单位认可规则。考试政策统一不意味着个人成本和使用场景相同。"},
	{Title: "复试风险必须进入择校模型", Category: "考研择校", Tags: []string{"复试", "初试", "录取风险"}, Content: "初试和复试都是研究生招生的重要组成部分。择校不仅看复试线，还要看差额比例、复试权重、考核内容、资格审查、同等学力要求和历年录取名单。对复试信息不透明或自身短板明显的方案，提高风险权重。"},
	{Title: "调剂不是确定性兜底", Category: "考研择校", Tags: []string{"调剂", "兜底", "考研风险"}, Content: "调剂受当年缺额、专业范围、初试科目、成绩要求和招生单位规则影响，不应在备考前被当作保证录取的兜底。主方案失利后的选择应同时包括调剂、二战、就业、实习或其他升学路径，并预先排序。"},
	{Title: "家庭预算要算总成本", Category: "家庭资源", Tags: []string{"家庭预算", "总成本", "机会成本"}, Content: "总成本包括学费、住宿与生活费、培训与考试费、迁移成本、无法工作的收入损失、失败后再次准备的成本。家庭讨论应明确可承受上限、资金来源和止损点，而不是只问能不能凑出第一年费用。"},
	{Title: "普通家庭不是只能选择保守", Category: "家庭资源", Tags: []string{"普通家庭", "风险管理", "可逆性"}, Content: "资源有限意味着更重视下行风险和可逆性，不等于必须放弃兴趣或高目标。可以用低成本验证、相邻专业、辅修、作品集、分阶段目标和保底路径降低风险，让进取建立在可承受失败之上。"},
	{Title: "医学法学师范等准入行业单独评估", Category: "专业选择", Tags: []string{"准入行业", "资格", "培养周期"}, Content: "涉及执业资格、规培、教师资格或法律职业资格等路径时，必须核对专业报考资格、培养年限、地区政策和目标岗位要求。不能只按专业热度判断，也不能把不同细分专业的准入规则混为一谈。"},
	{Title: "文科专业不能一刀切", Category: "专业选择", Tags: []string{"文科", "能力组合", "反绝对化"}, Content: "文科内部差异很大，岗位出口也受学校、城市、实习、写作研究能力、数据工具和资格门槛影响。正确问题不是文科有没有用，而是目标岗位、培养质量、竞争门槛、个人能力证据和备选路径分别是什么。"},
	{Title: "计算机专业不能只看行业高薪", Category: "专业选择", Tags: []string{"计算机", "高薪", "能力要求"}, Content: "计算机相关专业的结果受数学与编程基础、学校课程、项目实习、细分方向和市场周期影响。不能用头部薪资代表全体，也不能因AI工具进步就断言专业失效；应分析具体岗位任务和个人学习适配度。"},
	{Title: "金融专业重点核验平台与资源", Category: "专业选择", Tags: []string{"金融", "平台", "家庭资源"}, Content: "金融岗位分层明显，学历平台、城市、实习和证书可能影响机会，但不能简单断言没有家庭资源就不能学。应拆分银行、证券、保险、企业财务、监管与金融科技等岗位，分别验证招聘要求和普通毕业生去向。"},
	{Title: "艺术专业用作品与成本双重验证", Category: "专业选择", Tags: []string{"艺术", "作品集", "成本"}, Content: "艺术选择既要尊重长期投入，也要核算训练、材料、设备、作品集和地域成本。用持续作品、专业反馈、比赛或真实委托验证能力，并设计艺术主业、相关职业和通用技能三层出口，避免把家庭条件直接等同于资格。"},
	{Title: "AI时代判断任务而不是专业生死", Category: "AI与未来", Tags: []string{"AI", "任务分析", "职业变化"}, Content: "把岗位拆成信息检索、重复制作、复杂判断、沟通协商、责任承担和现场操作等任务，再判断哪些被自动化、哪些被增强、哪些会新增。专业不会整体同时消失，真正要更新的是工具能力、领域知识和可证明的解决问题能力。"},
	{Title: "选择大于努力的适用边界", Category: "决策框架", Tags: []string{"选择", "努力", "适用边界"}, Content: "选择会改变努力的回报结构，但没有信息、能力和持续执行，选择本身不会兑现。使用这条原则时应比较路径的门槛、概率、成本、上限、下限与可逆性，而不是用一句口号否定努力或责怪结果不佳的人。"},
	{Title: "中位数原则也要防止样本错配", Category: "决策框架", Tags: []string{"中位数", "样本", "数据质量"}, Content: "中位结果比头部故事稳健，但前提是样本与用户相似。不同学校层次、地区、专业方向、毕业年份和家庭条件不能混为一组。缺少同类样本时应降低置信度，并使用多个间接指标交叉验证。"},
	{Title: "咨询结论的置信度分级", Category: "回答规范", Tags: []string{"置信度", "证据", "引用"}, Content: "高置信结论需要最新官方规则或多项一致证据；中置信结论来自稳定框架与有限样本；低置信结论仅作为待验证假设。回答应标明信息日期、适用地区与改变结论的关键变量。没有可靠匹配时不引用、不编造。"},
}

